import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.B02wg2PO.js";const u=JSON.parse('{"title":"Logs, Activity & Observability","description":"","frontmatter":{},"headers":[],"relativePath":"operations/observability.md","filePath":"operations/observability.md"}'),n={name:"operations/observability.md"};function i(d,e,r,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="logs-activity-observability" tabindex="-1">Logs, Activity &amp; Observability <a class="header-anchor" href="#logs-activity-observability" aria-label="Permalink to &quot;Logs, Activity &amp; Observability&quot;">​</a></h1><p>Saidi records three separate streams, at three different resolutions, for three different purposes. Knowing which one answers your question saves most of the work.</p><table tabindex="0"><thead><tr><th>Stream</th><th>Resolution</th><th>Where</th><th>Retention</th></tr></thead><tbody><tr><td><strong>Run thread</strong> (<code>RunEvent[]</code>)</td><td>One entry per message, delegation, tool call, result</td><td>Mongo (run record), mirrored to <code>memory/runs/&lt;id&gt;/run.json</code></td><td>Life of the run</td></tr><tr><td><strong>Raw call log</strong> (<code>RawCallLogEntry</code>)</td><td>One entry per settled LLM call, full prompt and transcript</td><td><code>memory/runs/&lt;id&gt;/log.json</code></td><td>Forever, never truncated</td></tr><tr><td><strong>Activity log</strong> (<code>ActivityEvent</code>)</td><td>One entry per user-visible line across the whole install</td><td>Mongo, <code>memory/activity-log.json</code> as fallback</td><td>90-day TTL</td></tr></tbody></table><p>Plus two ledgers: <code>usageLog</code> on each run (tokens and cost per call) and the org-level credit ledger (money).</p><h2 id="the-run-thread" tabindex="-1">The run thread <a class="header-anchor" href="#the-run-thread" aria-label="Permalink to &quot;The run thread&quot;">​</a></h2><p>Every run carries an ordered <code>thread</code> of <code>RunEvent</code>s. Seven kinds, and no others:</p><table tabindex="0"><thead><tr><th><code>kind</code></th><th>What it marks</th></tr></thead><tbody><tr><td><code>message</code></td><td>A turn of prose — PRIME to you, you to PRIME, or an agent&#39;s report</td></tr><tr><td><code>delegation</code></td><td>PRIME (or a lead) handing work to a target</td></tr><tr><td><code>question</code></td><td>An agent asking something it cannot decide</td></tr><tr><td><code>answer</code></td><td>The reply to a question</td></tr><tr><td><code>tool</code></td><td>A tool invocation worth showing</td></tr><tr><td><code>result</code></td><td>The settled outcome of a delegation</td></tr><tr><td><code>system</code></td><td>Engine-authored notices: pauses, credit blocks, branch switches, completion</td></tr></tbody></table><p>Each event has <code>id</code>, <code>at</code> (epoch ms), <code>actor</code>, optional <code>to</code>, <code>text</code>, optional <code>detail</code>, optional <code>attachments</code>, <code>byUser</code>, and an optional <code>stats</code> block.</p><p>That <code>stats</code> block is where per-message accounting lives:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RunEventStats {</span></span>
<span class="line"><span>  inputTokens          fresh, uncached input tokens</span></span>
<span class="line"><span>  outputTokens         generated tokens</span></span>
<span class="line"><span>  cacheReadTokens?     tokens served from the prompt cache</span></span>
<span class="line"><span>  cacheCreationTokens? tokens written into the prompt cache</span></span>
<span class="line"><span>  ms?                  wall-clock duration of the call</span></span>
<span class="line"><span>  contextTokens?       context the session held on its LAST request (input + cache)</span></span>
<span class="line"><span>  costUsd?             USD at list prices</span></span>
<span class="line"><span>  costShared?          true when this cost is an apportioned share, not a quoted price</span></span>
<span class="line"><span>  model?               the model that produced it</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>contextTokens</code> is the number to watch for context pressure — it is occupancy, not consumption, so it does not accumulate the way the token counters do.</p><p>See <a href="/docs/concepts/runs">Runs</a> for how the thread relates to participants and branches.</p><h2 id="the-raw-call-log" tabindex="-1">The raw call log <a class="header-anchor" href="#the-raw-call-log" aria-label="Permalink to &quot;The raw call log&quot;">​</a></h2><p>The run thread is what a person reads. <code>memory/runs/&lt;id&gt;/log.json</code> is what you read when you need to know exactly what was sent to a model and exactly what came back.</p><p>Despite the name it is <strong>JSONL</strong> — one JSON object per line, appended with a single <code>O_APPEND</code> write per record so concurrent writers cannot interleave. Main-chat turns go to <code>memory/chat/log.json</code> under the pseudo-id <code>chat</code>.</p><p>Every record:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>runId</code></td><td>Owning run, or <code>chat</code></td></tr><tr><td><code>seq</code></td><td>Monotonic per-run index (seeded by counting existing lines on first write)</td></tr><tr><td><code>at</code></td><td>ISO-8601 completion time</td></tr><tr><td><code>actor</code></td><td><code>PRIME</code>, or the agent/project name</td></tr><tr><td><code>provider</code> / <code>model</code></td><td>Provider and the model string actually used</td></tr><tr><td><code>input</code></td><td><code>{ prompt, systemPrompt, tools, mcpServers, resume }</code> — the full request</td></tr><tr><td><code>output</code></td><td><code>{ messages, finalText, stopReason, messageId }</code> — the full transcript</td></tr><tr><td><code>usage</code></td><td>The <code>RunTokenUsage</code> block for this call</td></tr><tr><td><code>error</code></td><td>Present only if the call failed</td></tr><tr><td><code>taskId</code> / <code>mode</code></td><td>Checklist task and <code>ask</code> | <code>work</code></td></tr><tr><td><code>effort</code></td><td>Resolved effort tier</td></tr><tr><td><code>version</code></td><td>Orchestrator build that produced the entry</td></tr><tr><td><code>startedAt</code> / <code>durationMs</code> / <code>durationApiMs</code></td><td>Epoch ms start; total wall clock; provider inference time excluding local tool execution</td></tr><tr><td><code>terminalReason</code></td><td>Why the loop stopped</td></tr><tr><td><code>apiRetries</code> / <code>transient</code></td><td>Retry count, and whether the failure was classified transient</td></tr><tr><td><code>unpriced</code></td><td>Tokens were consumed but the provider quoted no price</td></tr></tbody></table><p><code>durationMs</code> minus <code>durationApiMs</code> is time spent in local tools — the single most useful number when a delegation feels slow but the model is not the bottleneck.</p><p><strong>There is no truncation, rotation, or pruning.</strong> That is a deliberate contract: a log that clips the interesting part is not a log. The only thing dropped is ephemeral SDK <code>system</code> ticks (<code>thinking_tokens</code>, <code>status</code>), which carry no information and would dominate the file.</p><p><strong>Redaction</strong> is exact-substring replacement of the resolved values of known secret keys — <code>mongodbUri</code>, <code>anthropicApiKey</code>, <code>anthropicAuthToken</code>, <code>claudeCodeOauthToken</code>, <code>openaiApiKey</code>, <code>saidiGithubToken</code> — each replaced with <code>[REDACTED &lt;key&gt;]</code>, plus the Mongo URI password separately. Values shorter than 8 characters are skipped. This is intentionally narrower than the entropy-based redaction used on the activity log: the raw log&#39;s job is fidelity.</p><p>Nothing in the codebase reads this file back. Inspect it yourself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># every call in a run, one line each</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{seq, at, actor, model, durationMs, durationApiMs, terminalReason}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memory/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/log.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the full request that produced call #7</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;select(.seq == 7) | .input&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/log.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># calls that consumed tokens but were never priced</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;select(.unpriced) | {seq, actor, model, usage}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> memory/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/log.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># time spent outside the model, per call</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;select(.durationApiMs) | {seq, actor, localMs: (.durationMs - .durationApiMs)}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memory/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/log.json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># total tokens by actor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;map(select(.usage)) | group_by(.actor)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">       | map({actor: .[0].actor,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">              input: (map(.usage.inputTokens) | add),</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">              output: (map(.usage.outputTokens) | add)})&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memory/runs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/log.json</span></span></code></pre></div><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><p>Verification records what it checked, not just its verdict. A completed task carries an <code>evidenceManifest</code> on its checklist item — stored with the run record, not as a separate file:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TaskEvidenceManifest {</span></span>
<span class="line"><span>  collectedAt       epoch ms</span></span>
<span class="line"><span>  reportSha256      sha256 of the agent&#39;s report, so an edited report is detectable</span></span>
<span class="line"><span>  artifacts[]       { path, kind: &#39;run-asset&#39;|&#39;workspace-file&#39;, size, sha256 }</span></span>
<span class="line"><span>  commands[]        { cmd, exitCode, ok, durationMs, outputTail?, cached? }</span></span>
<span class="line"><span>  provenCriteria[]  criteria a trusted check actually proved</span></span>
<span class="line"><span>  failedCriteria[]</span></span>
<span class="line"><span>  changes?          the git delta (below)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>changes</code> is collected by walking git: <code>{ branch, base, commits[{sha, subject}], files[{path, status, additions, deletions}], insertions, deletions }</code>. The <code>base</code> is the nearest <em>proven</em> ancestor among the hint plus <code>staging</code>, <code>develop</code>, <code>main</code>, <code>master</code> (each also tried as <code>origin/&lt;name&gt;</code>) — not whatever HEAD happened to be.</p><p>Clipping limits worth knowing, because they change what you see:</p><ul><li>at most 20 commits (<code>git log -n 20</code>)</li><li>at most 50 file rows — but <code>insertions</code> and <code>deletions</code> still sum over <strong>all</strong> files, so the totals and the row list can legitimately disagree</li><li>at most 200 artifacts hashed; the asset inventory is only built when a task declares an <code>assetCount</code> proof</li><li>git evidence commands time out at 15 s with a 4 MB output buffer</li></ul><p>Artifact paths are validated before hashing: absolute paths, <code>~</code>, symlinks, non-files and anything escaping the run directory are rejected.</p><p>See <a href="/docs/concepts/plans-and-tasks">Plans &amp; Tasks</a> for what turns evidence into a verdict.</p><h2 id="usage-and-cost" tabindex="-1">Usage and cost <a class="header-anchor" href="#usage-and-cost" aria-label="Permalink to &quot;Usage and cost&quot;">​</a></h2><p>Two record types, at two levels.</p><p><strong><code>RunTokenUsage</code></strong> — the per-call measurement:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inputTokens          fresh input, excluding cache</span></span>
<span class="line"><span>cacheReadTokens</span></span>
<span class="line"><span>cacheCreationTokens</span></span>
<span class="line"><span>outputTokens</span></span>
<span class="line"><span>costUsd?             USD at API list prices</span></span>
<span class="line"><span>unreported?          not one request in this call reported a token</span></span></code></pre></div><p><strong><code>RunUsageEntry</code></strong> extends it and is what lands in <code>run.usageLog</code>, one per settled call: <code>actor</code>, <code>at</code>, <code>models[]</code> (the model it actually ran on first), <code>unpriced?</code>, <code>reportChars?</code> (report length <em>before</em> budget clipping), <code>durationMs?</code>.</p><p>The three flags mean three different things, and Saidi keeps them apart on purpose:</p><ul><li><strong><code>unreported</code></strong> — the call ran and no request reported any token. Those zeros are the absence of a measurement, not a measurement of zero.</li><li><strong><code>unpriced</code></strong> — tokens demonstrably moved but no cost came back. Set when there is no <code>costUsd</code> and either <code>unreported</code> is true or any token counter is above zero. Typical causes: an aborted Anthropic call, or a custom endpoint with no rates configured.</li><li><strong><code>costShared</code></strong> — the cost on this <em>message</em> is an apportioned share of a turn the provider billed once, not a price anyone quoted for that message.</li></ul><p>Each participant also carries a rolled-up <code>usage</code>, a <code>contextTokens</code> reading, and an <code>unpricedCalls</code> counter, so you can see at a glance which agent&#39;s numbers are incomplete.</p><h3 id="how-a-turn-s-cost-is-split-across-messages" tabindex="-1">How a turn&#39;s cost is split across messages <a class="header-anchor" href="#how-a-turn-s-cost-is-split-across-messages" aria-label="Permalink to &quot;How a turn&#39;s cost is split across messages&quot;">​</a></h3><p>When a provider bills a turn as a unit and reports no per-message cost, the turn&#39;s cost is apportioned across that actor&#39;s <code>message</code> events by a token weight:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weight = inputTokens</span></span>
<span class="line"><span>       + cacheReadTokens      * 0.1</span></span>
<span class="line"><span>       + cacheCreationTokens  * 1.25</span></span>
<span class="line"><span>       + outputTokens         * 5</span></span></code></pre></div><p>The last share absorbs the remainder, so the shares sum to exactly what the turn cost, and every apportioned message is flagged <code>costShared</code>. If the turn was unpriced, or every message already carries a real price, nothing is apportioned. If no message reported usage at all, the whole turn is stamped on the last one rather than smeared.</p><p>Read <code>costShared</code> as: <em>this number is honest about being a share.</em> It is not an estimate dressed up as an invoice. See <a href="/docs/faq">the FAQ</a> for the short version.</p><h3 id="custom-endpoints" tabindex="-1">Custom endpoints <a class="header-anchor" href="#custom-endpoints" aria-label="Permalink to &quot;Custom endpoints&quot;">​</a></h3><p>Custom-provider pricing is configured in USD per million tokens, where <strong><code>0</code> means unpriced</strong> rather than free. A custom endpoint with unset rates therefore produces <code>unpriced</code> entries, not zero-cost ones.</p><h2 id="the-optimization-report" tabindex="-1">The optimization report <a class="header-anchor" href="#the-optimization-report" aria-label="Permalink to &quot;The optimization report&quot;">​</a></h2><p>When a run settles, it gets a <code>RunOptimizationReport</code> — the run&#39;s post-mortem in numbers:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>generatedAt, durationMs, taskExecutionMs</span></span>
<span class="line"><span>tasks, firstPassTasks, retries</span></span>
<span class="line"><span>workMissingFailures, proofFailures, semanticFailures,</span></span>
<span class="line"><span>environmentFailures, providerFailures</span></span>
<span class="line"><span>totalCostUsd, totalModelCalls, maxContextTokens</span></span></code></pre></div><p><code>tasks</code> versus <code>firstPassTasks</code> is the honest measure of how well the plan held. <code>taskExecutionMs</code> against <code>durationMs</code> tells you how much of the run was actually work rather than waiting on approvals. The five failure counters are the same <code>TaskFailureKind</code> taxonomy verification uses, so a run whose failures are mostly <code>environment_failure</code> has an infrastructure problem, not a planning one.</p><h2 id="the-activity-log" tabindex="-1">The activity log <a class="header-anchor" href="#the-activity-log" aria-label="Permalink to &quot;The activity log&quot;">​</a></h2><p>The activity log is the cross-run, cross-channel feed behind the dashboard. It is a Mongo collection with a <strong>90-day TTL</strong> — <code>id</code>, <code>t</code>, <code>orgId</code>, <code>actor</code>, <code>msg</code>, <code>detail</code>, <code>channel</code> (<code>main</code> or <code>run</code>), <code>conversationId</code>, <code>byUser</code>, <code>attachments[]</code>, and the same <code>stats</code> shape as a run event.</p><p>In-memory it is capped: 800 main entries, 200 per run, 1000 recent, 500 sealed, with a 50,000-entry journal. Unlike the raw call log, <code>msg</code> and <code>detail</code> go through entropy-based secret redaction — this stream is displayed, so it is scrubbed harder.</p><p><code>memory/activity-log.json</code> is the local fallback only; in a normal install Mongo holds it.</p><h2 id="inspecting-it-over-http" tabindex="-1">Inspecting it over HTTP <a class="header-anchor" href="#inspecting-it-over-http" aria-label="Permalink to &quot;Inspecting it over HTTP&quot;">​</a></h2><p>All routers mount under <code>/api</code>.</p><table tabindex="0"><thead><tr><th>Route</th><th>Returns</th></tr></thead><tbody><tr><td><code>GET /api/state</code></td><td>Full dashboard snapshot — runs plus activity</td></tr><tr><td><code>POST /api/state/reload</code></td><td>Re-hydrate stores from Mongo, including activity</td></tr><tr><td><code>GET /api/runs</code></td><td>Run list</td></tr><tr><td><code>GET /api/runs/search</code></td><td>Run search</td></tr><tr><td><code>GET /api/runs/:id</code></td><td>The full run record, including <code>thread</code>, <code>usageLog</code>, <code>verificationLog</code></td></tr><tr><td><code>GET /api/runs/:id/git</code></td><td>Branch, dirty state, commits, changed files</td></tr><tr><td><code>GET /api/runs/:id/git/compare</code>, <code>/git/diff</code>, <code>/git/file</code>, <code>/git/worktree</code></td><td>Diff views</td></tr><tr><td><code>GET /api/runs/:id/files?path=</code></td><td>Browse a run directory</td></tr><tr><td><code>GET /api/runs/:id/fs?path=</code></td><td>Read a file under the run directory</td></tr><tr><td><code>GET /api/credits</code></td><td>Wallet balance and allowance (cloud only)</td></tr><tr><td><code>GET /api/credits/usage?limit=N</code></td><td>Usage ledger; limit clamped 1–500, default 250</td></tr><tr><td><code>GET /api/admin/metrics</code></td><td>Platform aggregates over a 30-day window</td></tr><tr><td><code>GET /api/reflexes/log</code></td><td>Reflex fire log</td></tr><tr><td><code>GET /api/voice/metrics</code></td><td>Last 50 voice turns</td></tr></tbody></table><p>Two things to note. There is <strong>no</strong> <code>GET /api/runs/:id/events</code> and no SSE stream — live thread updates arrive over the WebSocket as <code>run_event</code>, <code>run_update</code> and <code>state_dirty</code> frames, and everything else you pull from <code>GET /api/runs/:id</code>. And the raw <code>log.json</code> is reachable only through the file routes above, which cap listings at 500 entries, inline content at 256 KB, and file size at 8 MB.</p><p><code>GET /api/admin/metrics</code> returns <code>orgs</code>, <code>users</code>, <code>liveRuns</code>, <code>creditsCharged30d</code>, <code>rawCost30d</code>, <code>margin30d</code>. <code>rawCost30d</code> is provider cost before margin; <code>creditsCharged30d</code> is what was debited from wallets.</p><h2 id="the-credit-ledger" tabindex="-1">The credit ledger <a class="header-anchor" href="#the-credit-ledger" aria-label="Permalink to &quot;The credit ledger&quot;">​</a></h2><p>Money is tracked separately from tokens. Each <code>CreditLedgerEntry</code> is <code>id</code>, <code>at</code>, <code>delta</code> (negative for a debit), <code>reason</code> (one of <code>run.usage</code>, <code>chat.usage</code>, <code>topup.manual</code>, <code>adjustment</code>, <code>grant.admin</code>, <code>revoke.admin</code>), plus <code>runId</code>, <code>actor</code>, <code>orgId</code>, <code>userId</code>, <code>rawCostUsd</code> (the raw provider cost before margin), <code>models[]</code>, and <code>balanceAfter</code>.</p><p>On disk: <code>memory/credits.json</code> and <code>memory/credit-ledger.jsonl</code>. The API and in-memory view keep the most recent 500 entries.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># what a single run cost the wallet</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;select(.runId == &quot;&lt;runId&gt;&quot;) | {at, delta, rawCostUsd, balanceAfter, models}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memory/credit-ledger.jsonl</span></span></code></pre></div><p>Because <code>rawCostUsd</code> is recorded alongside <code>delta</code>, the ledger reconciles against the run&#39;s own <code>usageLog</code> — if they disagree, the run has <code>unpriced</code> entries. Which limits and caps produce a pause is covered in <a href="/docs/reference/settings">Settings</a>.</p>`,63)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
